package com.graduation.flower.domain; import org.springframework.boot.CommandLineRunner;import org.springframework.core.annotation.Order;import org.springframework.context.annotation.*;
@org.springframework.context.annotation.Profile({"dev","test","ci"}) @Configuration public class ProjectDataSeed{@Bean @Order(10) CommandLineRunner seedProject(FlowerProductRepository products){return args->{if(products.count()==0){var x=new FlowerProduct();x.setName("香槟玫瑰小花束");x.setCategory("鲜切花");x.setMeaning("温柔与珍惜");x.setColor("香槟色");x.setPrice(new java.math.BigDecimal("89"));x.setStock(36);x.setStatus("ON_SALE");products.save(x);}};}}
